const kdenseZip=`https://github.com/K-Dense-AI/scientific-agent-skills/archive/${KDENSE_COMMIT}.zip`;
const kdenseLicense=`https://github.com/K-Dense-AI/scientific-agent-skills/blob/${KDENSE_COMMIT}/LICENSE.md`;
export const plazaSkills=[
 {id:'scientific-writing',title:'科研论文写作',group:'写作与构思',icon:'pen',tone:'blue',description:'按科研写作结构组织论文内容，关注论证、证据与引用。',inputs:'研究主题、提纲、研究材料和投稿要求',output:'科研稿件结构与写作建议',author:'K-Dense',license:'MIT',version:KDENSE_COMMIT,source:kdense('scientific-writing'),licenseUrl:kdenseLicense,downloadUrl:kdenseZip,downloadLabel:'下载完整项目',dependencies:'部分辅助脚本需要 Python；具体要求以原项目说明为准。'},
 {id:'literature-review',title:'文献综述',group:'文献与引用',icon:'book',tone:'teal',description:'围绕研究问题检索、筛选和综合文献，整理研究脉络。',inputs:'研究问题、检索范围和已有文献',output:'文献整理与综述建议',author:'K-Dense',license:'MIT',version:KDENSE_COMMIT,source:kdense('literature-review'),licenseUrl:kdenseLicense,downloadUrl:kdenseZip,downloadLabel:'下载完整项目',dependencies:'文献检索涉及联网，部分脚本需要 Python 和相应依赖。'},
 {id:'citation-management',title:'引用管理',group:'文献与引用',icon:'search',tone:'violet',description:'帮助整理引文、文献元数据与参考文献格式。',inputs:'参考文献信息、引文和目标格式',output:'引用管理与核对建议',author:'K-Dense',license:'MIT',version:KDENSE_COMMIT,source:kdense('citation-management'),licenseUrl:kdenseLicense,downloadUrl:kdenseZip,downloadLabel:'下载完整项目',dependencies:'在线元数据查询需要联网，部分脚本需要 Python 和 requests。'},
 {id:'peer-review',title:'科研稿件审阅',group:'表达与审校',icon:'shield',tone:'rose',description:'从研究设计、论证、证据和行文等方面审阅科研稿件。',inputs:'有权处理的稿件及审阅要求',output:'结构化审阅意见',author:'K-Dense',license:'MIT',version:KDENSE_COMMIT,source:kdense('peer-review'),licenseUrl:kdenseLicense,downloadUrl:kdenseZip,downloadLabel:'下载完整项目',dependencies:'部分辅助脚本需要 Python；请按原项目说明配置。'},
 {id:'research-lookup',title:'研究资料检索',group:'文献与引用',icon:'search',tone:'indigo',description:'查找研究资料，辅助核对信息来源。',inputs:'研究问题、关键词和拟核对的问题',output:'研究资料及来源线索',author:'K-Dense',license:'MIT',version:KDENSE_COMMIT,source:kdense('research-lookup'),licenseUrl:kdenseLicense,downloadUrl:kdenseZip,downloadLabel:'下载完整项目',dependencies:'需要联网和 Parallel CLI，检索内容会发送至 Parallel；部分功能需要第三方 API 密钥。'},
 {id:'humanizer',title:'Humanizer 英文表达优化',group:'表达与审校',icon:'spark',tone:'amber',description:'识别并改善英文文本中的模板化表达，保留作者原意。',inputs:'需要修改的英文文本与写作要求',output:'修改后的文本与表达建议',author:'blader',license:'MIT',version:HUMANIZER_COMMIT,source:`https://github.com/blader/humanizer/tree/${HUMANIZER_COMMIT}`,licenseUrl:`https://github.com/blader/humanizer/blob/${HUMANIZER_COMMIT}/LICENSE`,downloadUrl:`https://github.com/blader/humanizer/archive/${HUMANIZER_COMMIT}.zip`,downloadLabel:'下载完整项目',dependencies:'需要支持 SKILL.md 的 AI 智能体；结果请由作者审阅。'}
];
const groups=['全部','写作与构思','文献与引用','表达与审校'];
const glyph=(name,size=20)=>{const paths={download:'M12 3v12m-5-5 5 5 5-5M4 17v3h16v-3',spark:'M12 2l1.8 5.5L19 9l-5.2 1.5L12 16l-1.8-5.5L5 9l5.2-1.5L12 2zm7 13 .8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8L19 15z'};return paths[name]?`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`:icon(name,size);};
const download=s=>`<a class="ap-primary" href="${esc(s.downloadUrl)}" target="_blank" rel="noopener noreferrer">${glyph('download',16)} ${esc(s.downloadLabel)} ↗</a>`;
function card(s){return `<article class="ap-card ap-${esc(s.tone)}"><div class="ap-card-top"><span class="ap-icon">${glyph(s.icon,24)}</span><span class="ap-card-type">${esc(s.author)} · ${esc(s.license)}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="ap-tags"><span>${esc(s.group)}</span><span>开源 Skill</span></div><div class="ap-actions"><button class="ap-detail-btn" type="button" data-ap-detail="${esc(s.id)}">查看详情 <span aria-hidden="true">↗</span></button>${download(s)}</div></article>`;}
function detail(s){return `<div class="ap-dialog-head"><div><span class="ap-eyebrow">OPEN-SOURCE SKILL</span><h2 id="ap-detail-title">${esc(s.title)}</h2><p>${esc(s.description)}</p></div><button type="button" class="ap-close" aria-label="关闭详情" data-ap-close>×</button></div><div class="ap-detail-body"><div class="ap-detail-row"><span>项目作者</span><strong>${esc(s.author)}</strong></div><div class="ap-detail-row"><span>开源许可</span><strong><a href="${esc(s.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(s.license)} · 查看许可 ↗</a></strong></div><div class="ap-detail-row"><span>固定版本</span><strong>${esc(s.version.slice(0,12))}</strong></div><div class="ap-detail-row"><span>准备材料</span><strong>${esc(s.inputs)}</strong></div><div class="ap-detail-row"><span>产出内容</span><strong>${esc(s.output)}</strong></div><div class="ap-detail-note"><strong>使用说明</strong><p>本资源由第三方开源项目提供并维护，PaperKnow 仅整理分享，未接入站内服务。请自行核对功能、效果及适用性。</p><p>下载的是作者的完整开源项目${s.author==='K-Dense'?'（含多个 Skill，文件较大）':''}。解压后按原项目说明选择所需 Skill，放入支持 SKILL.md 的 AI 智能体工具中；安装位置以所用工具为准。</p><p>${esc(s.dependencies)} 上游项目可能包含脚本和联网调用，请在使用前阅读原项目说明。</p></div><div class="ap-dialog-actions">${download(s)}<a class="ap-secondary" href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">查看 Skill 源码 ↗</a></div></div>`;}
export function mountAiPlaza(root){
 if(!root)return;
 root.innerHTML=`<main class="ai-plaza"><header class="ap-hero"><div class="ap-hero-copy"><span class="ap-eyebrow"><span></span> AI RESEARCH PLAZA</span><h1>让每一步研究，<br><em>都有更好的方法。</em></h1><p>发现适合研究与写作的第三方开源 Skill，了解项目后按需下载使用。</p><button type="button" class="ap-hero-link" data-ap-scroll>探索写作 Skill <span aria-hidden="true">↓</span></button></div><div class="ap-hero-art" aria-hidden="true"><div class="ap-orbit ap-orbit-one"></div><div class="ap-orbit ap-orbit-two"></div><div class="ap-art-card"><span class="ap-art-mark">✦</span><div><small>RESEARCH WORKFLOW</small><strong>从想法到成果</strong></div><i></i><i></i><i></i></div><span class="ap-art-chip ap-chip-one">研究构思</span><span class="ap-art-chip ap-chip-two">文献与引用</span><span class="ap-art-chip ap-chip-three">写作与审校</span></div></header><section id="ap-skills" class="ap-library"><div class="ap-section-heading"><div><span class="ap-kicker">SKILL LIBRARY</span><h2>开源科研写作 Skill</h2><p>广场整理分享第三方开源项目，由原作者或社区维护，未接入 PaperKnow 站内服务。请在使用前查看项目来源、许可和要求，自行核对功能、效果与适用性。</p></div><div class="ap-search">${icon('search',18)}<input type="search" data-ap-search placeholder="搜索 Skill 或使用场景" aria-label="搜索 Skill 或使用场景"></div></div><div class="ap-filters" role="group" aria-label="Skill 分类">${groups.map((group,index)=>`<button type="button" data-ap-group="${esc(group)}" aria-pressed="${index===0}">${esc(group)}</button>`).join('')}</div><div class="ap-results-head"><span data-ap-count aria-live="polite"></span><span>适用于支持 SKILL.md 的 AI 智能体工具</span></div><div class="ap-grid" data-ap-grid></div><div class="ap-empty" data-ap-empty hidden><strong>没有找到相关 Skill</strong><p>试试其他关键词或切换分类。</p><button type="button" data-ap-reset>查看全部 Skill</button></div></section><section class="ap-use"><div><span class="ap-kicker">GET STARTED</span><h2>简单三步，开始使用</h2><p>选择开源 Skill，按原项目说明在支持的智能体工具中使用。</p></div><ol><li><span>01</span><div><strong>选择并下载</strong><p>查看 Skill 的项目来源、许可和使用要求。</p></div></li><li><span>02</span><div><strong>解压并安装</strong><p>解压完整项目，按需安装其中的 Skill。</p></div></li><li><span>03</span><div><strong>提供任务与资料</strong><p>提供任务与资料，检查结果并核对来源。</p></div></li></ol><div class="ap-docs">安装位置与加载方式可能因工具版本而异：<a href="https://developers.openai.com/codex/skills/" target="_blank" rel="noopener noreferrer">Codex 说明 ↗</a><a href="https://code.claude.com/docs/en/skills" target="_blank" rel="noopener noreferrer">Claude Code 说明 ↗</a></div></section><dialog class="ap-dialog" aria-labelledby="ap-detail-title" data-ap-dialog></dialog></main>`;
 const search=root.querySelector('[data-ap-search]'),grid=root.querySelector('[data-ap-grid]'),empty=root.querySelector('[data-ap-empty]'),count=root.querySelector('[data-ap-count]'),dialog=root.querySelector('[data-ap-dialog]');let group='全部';
 const draw=()=>{const q=search.value.trim().toLowerCase(),list=plazaSkills.filter(s=>(group==='全部'||s.group===group)&&(!q||[s.title,s.description,s.group,s.inputs,s.output,s.id,s.author,s.license].join(' ').toLowerCase().includes(q)));grid.innerHTML=list.map(card).join('');empty.hidden=list.length!==0;count.textContent=`${list.length} 个 Skill`;};
 search.addEventListener('input',draw);root.querySelectorAll('[data-ap-group]').forEach(button=>button.addEventListener('click',()=>{group=button.dataset.apGroup;root.querySelectorAll('[data-ap-group]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));draw();}));root.querySelector('[data-ap-reset]').addEventListener('click',()=>{search.value='';group='全部';root.querySelectorAll('[data-ap-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.apGroup===group)));draw();});
 const plaza=root.querySelector('.ai-plaza');
 plaza.addEventListener('click',event=>{if(event.target.closest('[data-ap-scroll]')){root.querySelector('#ap-skills')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});} const open=event.target.closest('[data-ap-detail]');if(open&&root.contains(open)){const skill=plazaSkills.find(s=>s.id===open.dataset.apDetail);if(!skill)return;dialog.innerHTML=detail(skill);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}if(event.target.closest('[data-ap-close]')){if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}});draw();
}
